int APIENTRY wWinMain(_In_ HINSTANCE instance, _In_opt_ HINSTANCE prev,
                      _In_ wchar_t *command_line, _In_ int show_command) {
  // Attach to console when present (e.g., 'flutter run') or create a
  // new console when running with a debugger.
  if (!::AttachConsole(ATTACH_PARENT_PROCESS) && ::IsDebuggerPresent()) {
    CreateAndAttachConsole();
  }

  // Initialize COM, so that it is available for use in the library and/or
  // plugins.
  ::CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);

  flutter::DartProject project(L"data");

  std::vector<std::string> command_line_arguments =
      GetCommandLineArguments();

  project.set_dart_entrypoint_arguments(std::move(command_line_arguments));

  FlutterWindow window(project);
  Win32Window::Point origin(10, 10);
  Win32Window::Size size(1280, 720);
  if (!window.CreateAndShow(L"flowy_sdk_example", origin, size)) {
    return EXIT_FAILURE;
  }
  window.SetQuitOnClose(true);

  ::MSG msg;
  while (::GetMessage(&msg, nullptr, 0, 0)) {
    ::TranslateMessage(&msg);
    ::DispatchMessage(&msg);
  }

  ::CoUninitialize();
  return EXIT_SUCCESS;
}

'use client'

import { useLiveNodeOverrides, useRegistry, useScene, type WindowNode } from '@pascal-app/core'
import {
  createMaterial,
  DEFAULT_WINDOW_MATERIAL,
  useNodeEvents,
  useViewer,
} from '@pascal-app/viewer'
import { useLayoutEffect, useMemo, useRef } from 'react'
import type { Mesh } from 'three'
import { RoofFaceHostFrame } from '../shared/roof-face-host'

export const WindowRenderer = ({ node }: { node: WindowNode }) => {
  const ref = useRef<Mesh>(null!)

  useRegistry(node.id, 'window', ref)
  useLayoutEffect(() => {
    useScene.getState().markDirty(node.id)
  }, [node.id])
  const handlers = useNodeEvents(node, 'window')
  const shading = useViewer((s) => s.shading)
  const liveOverrides = useLiveNodeOverrides((s) => s.get(node.id))
  const renderNode = liveOverrides ? ({ ...node, ...liveOverrides } as WindowNode) : node
  const isTransient = !!(node.metadata as Record<string, unknown> | null)?.isTransient

  const material = useMemo(() => {
    const mat = node.material
    if (!mat) return DEFAULT_WINDOW_MATERIAL(shading)
    return createMaterial(mat, shading)
  }, [
    shading,
    node.material,
    node.material?.preset,
    node.material?.properties,
    node.material?.texture,
  ])

  const mesh = (
    <mesh
      material={material}
      position={renderNode.position}
      ref={ref}
      rotation={renderNode.rotation}
      visible={renderNode.visible}
      {...(isTransient ? {} : handlers)}
    >
      <boxGeometry args={[0, 0, 0]} />
    </mesh>
  )

  if (!renderNode.roofSegmentId) return mesh
  return (
    <RoofFaceHostFrame roofFace={renderNode.roofFace} roofSegmentId={renderNode.roofSegmentId}>
      {mesh}
    </RoofFaceHostFrame>
  )
}

export default WindowRenderer

import View from "inspector/view"
const now = window.performance?.now ? () => performance.now() : () => new Date().getTime()

class PerformanceView extends View {
  static title = "Performance"
  static template = "performance"

  constructor() {
    super(...arguments)
    this.documentView = this.compositionController.documentView

    this.data = {}
    this.track("documentView.render")
    this.track("documentView.sync")
    this.track("documentView.garbageCollectCachedViews")
    this.track("composition.replaceHTML")

    this.render()
  }

  track(methodPath) {
    this.data[methodPath] = { calls: 0, total: 0, mean: 0, max: 0, last: 0 }
    const parts = methodPath.split(".")
    const propertyNames = parts.slice(0, parts.length - 1)
    const methodName = parts[parts.length - 1]

    let object = this

    propertyNames.forEach((propertyName) => {
      object = object[propertyName]
    })

    const original = object[methodName]

    object[methodName] = function() {
      const started = now()
      const result = original.apply(object, arguments)
      const timing = now() - started
      this.record(methodPath, timing)
      return result
    }.bind(this)
  }

  record(methodPath, timing) {
    const data = this.data[methodPath]
    data.calls += 1
    data.total += timing
    data.mean = data.total / data.calls
    if (timing > data.max) {
      data.max = timing
    }
    data.last = timing
    return this.render()
  }

  round(ms) {
    return Math.round(ms * 1000) / 1000
  }
}

Trix.Inspector.registerView(PerformanceView)

export default class LineBreakInsertion {
  constructor(composition) {
    this.composition = composition
    this.document = this.composition.document
    const selectedRange = this.composition.getSelectedRange()
    this.startPosition = selectedRange[0]
    this.endPosition = selectedRange[1]

    this.startLocation = this.document.locationFromPosition(this.startPosition)
    this.endLocation = this.document.locationFromPosition(this.endPosition)

    this.block = this.document.getBlockAtIndex(this.endLocation.index)
    this.breaksOnReturn = this.block.breaksOnReturn()
    this.previousCharacter = this.block.text.getStringAtPosition(this.endLocation.offset - 1)
    this.nextCharacter = this.block.text.getStringAtPosition(this.endLocation.offset)
  }

  shouldInsertBlockBreak() {
    if (this.block.hasAttributes() && this.block.isListItem() && !this.block.isEmpty()) {
      return this.startLocation.offset !== 0
    } else {
      return this.breaksOnReturn && this.nextCharacter !== "\n"
    }
  }

  shouldBreakFormattedBlock() {
    return (
      this.block.hasAttributes() &&
      !this.block.isListItem() &&
      (this.breaksOnReturn && this.nextCharacter === "\n" || this.previousCharacter === "\n")
    )
  }

  shouldDecreaseListLevel() {
    return this.block.hasAttributes() && this.block.isListItem() && this.block.isEmpty()
  }

  shouldPrependListItem() {
    return this.block.isListItem() && this.startLocation.offset === 0 && !this.block.isEmpty()
  }

  shouldRemoveLastBlockAttribute() {
    return this.block.hasAttributes() && !this.block.isListItem() && this.block.isEmpty()
  }
}
